import {parseSrt,mapSubtitles} from './subtitles.js';
import {makeReferenceStyle} from './reference-style.js';
import {updateTeaching,tutorialCard} from './teaching-video.js';
import {effectHint} from './lesson-core.js';
import {selection,requireModelCalls} from './provider-ui.js';
import {boundaries,recipes,report,restoreNotes} from './breakdown-core.js';
const $=id=>document.getElementById(id),player=$('ref-player');
let reference=null,samples=[],shots=[],lastReport='',scanning=false,refURL=null,subtitleCues=[];
const say=t=>$('ref-status').textContent=t;
const guide=$('guide');function openGuide(){guide.showModal();$('guide-close').focus()};$('help').onclick=openGuide;$('help-top').onclick=openGuide;$('guide-close').onclick=() => guide.close();$('guide-start').onclick=()=>guide.close();openGuide();
function event(el,name){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{clean();reject(Error('读取视频超时，请换用浏览器支持的 MP4'))},15000);function clean(){clearTimeout(timer);el.removeEventListener(name,done);el.removeEventListener('error',fail)}function done(){clean();resolve()}function fail(){clean();reject(Error('视频无法解码'))}el.addEventListener(name,done,{once:true});el.addEventListener('error',fail,{once:true})})}
function invalidate(){updateTeaching(shots,samples);lastReport='';$('ref-output').textContent='内容已变更，请重新生成报告。'}
async function load(file){if(scanning)return;subtitleCues=[];$('ref-transcript').value='';reference=null;lastReport='';samples=[];shots=[];$('ref-shots').replaceChildren();updateTeaching(shots,samples);player.pause();if(refURL)URL.revokeObjectURL(refURL);refURL=URL.createObjectURL(file);const ready=event(player,'loadedmetadata');player.src=refURL;await ready;if(!Number.isFinite(player.duration)||player.duration<=0||player.duration>600)throw Error('请选择时长不超过 10 分钟的视频');reference={name:file.name,duration:player.duration,width:player.videoWidth,height:player.videoHeight};samples=[];shots=[];$('ref-shots').replaceChildren();invalidate();say(`已载入 ${file.name} · ${player.duration.toFixed(1)} 秒。点击抽帧开始。`)}
$('ref-file').onchange=async e=>{try{if(e.target.files[0]){await load(e.target.files[0]);$('ref-scan').click()}}catch(e){reference=null;say(e.message)}finally{e.target.value=''}};
$('ref-demo').onclick=async()=>{try{const r=await fetch(new URL('./demo/shot2.mp4',import.meta.url));if(!r.ok)throw Error('示例加载失败');await load(new File([await r.blob()],'demo-reference.mp4',{type:'video/mp4'}));$('ref-transcript').value='想让视频更有节奏？先展示结果，再补充过程。收藏这套剪辑方法。';say('示例已载入。文案是演示文本，并非示例视频的原声。请点击抽帧。')}catch(e){say(e.message)}};
function render(){const box=$('ref-shots');box.replaceChildren();shots.forEach((s,i)=>{const card=document.createElement('div');card.className='shot-card';const pic=samples.reduce((best,f)=>Math.abs(f.time-(s.start+s.end)/2)<Math.abs(best.time-(s.start+s.end)/2)?f:best,samples[0]);if(pic){const img=document.createElement('img');img.src=pic.image;img.alt=`第 ${i+1} 段的参考帧，采样于 ${pic.time.toFixed(1)} 秒`;card.append(img)}const play=document.createElement('button');play.className='secondary';play.textContent=`${i+1} · ${s.start.toFixed(1)}–${s.end.toFixed(1)} 秒 ▶`;play.onclick=async()=>{try{player.currentTime=s.start;await player.play()}catch(e){say(e.message)}};card.append(play);for(const [key,labelText] of [['note','画面 / 动作观察'],['copy','该段原文案']]){const label=document.createElement('label');label.textContent=labelText;const input=document.createElement('textarea');input.maxLength=1000;input.value=s[key]||'';input.placeholder=key==='note'?'例如：全景交代环境，随后切到产品特写':'请填写实际字幕或口播';input.oninput=()=>{s[key]=input.value;invalidate()};label.append(input);card.append(label)}const label=document.createElement('label');label.textContent='复现方式（采样建议，可手动校正）';const select=document.createElement('select');Object.keys(recipes).forEach(k=>{const op=document.createElement('option');op.textContent=k;op.value=k;select.append(op)});select.value=s.effect;select.onchange=()=>{s.effect=select.value;s.evidence='你手动选择的复现方式，不代表已识别原片效果。';render();invalidate()};label.append(select);card.append(label);if(i>0){const merge=document.createElement('button');merge.className='secondary';merge.textContent='与上一段合并';merge.onclick=()=>{shots[i-1].end=s.end;shots[i-1].note=[shots[i-1].note,s.note].filter(Boolean).join('；');shots[i-1].copy=[shots[i-1].copy,s.copy].filter(Boolean).join(' ');shots.splice(i,1);render();invalidate()};card.append(merge)}const evidence=document.createElement('p');evidence.className='effect-evidence';evidence.textContent=s.evidence||'复现方式是学习建议，不代表原片工程识别。';card.append(evidence,tutorialCard(s));box.append(card)});updateTeaching(shots,samples)}
$('ref-scan').onclick=async()=>{if(!reference)return say('请先选择参考视频');if(scanning)return;scanning=true;player.controls=false;const controls=['ref-creator','ref-source-url','ref-apply-style','ref-file','ref-demo','ref-scan','ref-mark','ref-threshold','ref-project-file','ref-save-project','ref-report','ref-ai'];controls.forEach(id=>$(id).disabled=true);try{player.pause();samples=[];const canvas=document.createElement('canvas');canvas.width=320;canvas.height=Math.max(1,Math.round(320*reference.height/reference.width));if(canvas.height>570){canvas.height=570;canvas.width=Math.max(1,Math.round(570*reference.width/reference.height))}const ctx=canvas.getContext('2d',{willReadFrequently:true});const tiny=document.createElement('canvas');tiny.width=24;tiny.height=24;const tc=tiny.getContext('2d',{willReadFrequently:true});const count=Math.min(120,Math.max(2,Math.ceil(reference.duration*2)));for(let i=0;i<count;i++){const time=Math.max(0,Math.min(reference.duration-.001,i*reference.duration/count));if(player.readyState<2)await event(player,'loadeddata');if(Math.abs(player.currentTime-time)>.001){const done=event(player,'seeked');player.currentTime=Math.max(0,time);await done}ctx.drawImage(player,0,0,canvas.width,canvas.height);tc.drawImage(player,0,0,24,24);const rgba=tc.getImageData(0,0,24,24).data,pixels=[];for(let j=0;j<rgba.length;j+=4)pixels.push(rgba[j],rgba[j+1],rgba[j+2]);samples.push({time,pixels,image:canvas.toDataURL('image/jpeg',.6)});say(`抽帧 ${i+1}/${count}，请暂勿操作参考视频…`)}shots=boundaries(samples,reference.duration,Number($('ref-threshold').value)).map(s=>({...s,note:'',copy:'',effect:effectHint(samples,s).effect,evidence:effectHint(samples,s).evidence}));render();lastReport=localReport();$('ref-output').textContent=lastReport;player.currentTime=0;say(`报告已生成：${samples.length} 个采样帧、${shots.length} 个候选区间。播放核对；漏切可暂停后添加切点，多切可合并。`)}catch(e){say('抽帧失败：'+e.message)}finally{scanning=false;player.controls=true;controls.forEach(id=>$(id).disabled=id==='ref-ai')}};
$('ref-mark').onclick=()=>{if(!shots.length)return say('请先抽帧');const t=player.currentTime;const i=shots.findIndex(s=>t>s.start+.1&&t<s.end-.1);if(i<0)return say('切点太靠近已有边界');if(shots.length>=40)return say('最多保留 40 段');const old=shots[i];shots.splice(i,1,{...old,end:t},{...old,start:t,copy:'',note:''});render();invalidate();say(`已在 ${t.toFixed(2)} 秒添加切点`)};
function localReport(){if(!reference||!shots.length)throw Error('请先选择视频并完成抽帧');const transcript=$('ref-transcript').value.trim()||shots.map(s=>s.copy).filter(Boolean).join('\n');return report({...reference,shots,transcript})+'\n\n## 来源记录（用户填写，未核验）\n'+$('ref-creator').value.slice(0,80)+'\n'+$('ref-source-url').value.slice(0,2000)}
$('ref-report').onclick=()=>{try{lastReport=localReport();$('ref-output').textContent=lastReport;say('本地报告已生成：基于采样和输入文本的建议，未调用 AI')}catch(e){say(e.message)}};
$('ref-transcript').oninput=invalidate;
$('ref-textfile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('文案文件请小于 100KB');const raw=await f.text();if(/\.srt$/i.test(f.name)){if(!reference)throw Error('请先加载对应的视频，再导入 SRT');subtitleCues=parseSrt(raw,reference.duration);const text=subtitleCues.map(c=>c.copy).join('\n');if(text.length>12000)throw Error('文案最多 12000 字符');$('ref-transcript').value=text;say('已读取真实字幕时间。完成拉片后点击“按 SRT 分配镜头文案”，会替换各镜头已有文案。')}else{if(raw.length>12000)throw Error('文案最多 12000 字符');subtitleCues=[];$('ref-transcript').value=raw;say('普通文案已导入；没有时间信息，不会编造字幕时间。')}invalidate()}catch(e){subtitleCues=[];say(e.message)}finally{e.target.value=''}};
$('ref-map-srt').onclick=()=>{try{if(scanning)throw Error('请等待抽帧完成');shots=mapSubtitles(shots,subtitleCues);render();invalidate();say('字幕已按实际时间与候选镜头重叠区间分配；跨镜头字幕可能出现在多个镜头中。')}catch(e){say(e.message)}};
$('ref-download').onclick=()=>{if(!lastReport)return say('请先重新生成报告');const url=URL.createObjectURL(new Blob([lastReport],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ClipPilot-拉片报告.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};
$('ref-ai').onclick=async()=>{try{requireModelCalls();const baseline=localReport();if(!$('api').value||!$('token').value)throw Error('请先在“连接自己的 AI 后端”配置地址和访问令牌；或使用本地报告');const base=new URL($('api').value);if(base.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(base.hostname))throw Error('后端地址必须使用 HTTPS');if(!confirm('将向你配置的模型服务发送最多 12 张低清抽帧、镜头笔记及文案。不发送原视频或音轨。是否继续？'))return;$('ref-ai').disabled=true;say('视觉模型分析中，可能需要约 1 分钟…');const frames=Array.from({length:Math.min(12,samples.length)},(_,i)=>samples[Math.round(i*(samples.length-1)/Math.max(1,Math.min(12,samples.length)-1))]).map(({time,image})=>({time,image}));const response=await fetch(base.origin+'/api/analyze',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+$('token').value},body:JSON.stringify({provider:selection('vision'),reference,frames,transcript:$('ref-transcript').value,shots:shots.map(({start,end,note,copy,effect})=>({start,end,note,copy,effect}))}),signal:AbortSignal.timeout(95000)});const data=await response.json();if(!response.ok)throw Error(data.error||'AI 分析失败');if(typeof data.analysis!=='string')throw Error('AI 返回格式不正确');lastReport=baseline+'\n\n## AI 深度分析（模型推断，请核对）\n'+data.analysis;$('ref-output').textContent=lastReport;say(`AI 分析完成（${data.provider||'后端默认'} / ${data.model||'已配置模型'}）。仅根据所传抽帧与文本，可能漏判动作和特效。`)}catch(e){say('AI 分析未完成：'+e.message)}finally{$('ref-ai').disabled=true}};

$('ref-save-project').onclick=()=>{try{
 localReport();const data={type:'clippilot-reference-notes',version:1,reference,shots,transcript:$('ref-transcript').value};
 const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ClipPilot-拉片笔记.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);say('笔记备份已下载，不含源视频或抽帧图片。');
}catch(e){say(e.message)}};
$('ref-project-file').onchange=async e=>{try{
 if(scanning)throw Error('请等待抽帧完成');if(!reference||!samples.length)throw Error('请先加载并抽帧备份对应的源视频');
 const file=e.target.files[0];if(!file)return;if(file.size>500000)throw Error('笔记文件需小于 500KB');
 const loaded=restoreNotes(JSON.parse(await file.text()),reference);shots=loaded.shots;$('ref-transcript').value=loaded.transcript;render();lastReport=localReport();$('ref-output').textContent=lastReport;say('拉片笔记与镜头区间已恢复，本地报告已更新。');
}catch(e){say('恢复失败：'+e.message)}finally{e.target.value=''}};

$('ref-apply-style').onclick=()=>{try{const profile=makeReferenceStyle({creator:$('ref-creator').value,url:$('ref-source-url').value,reference,shots});document.dispatchEvent(new CustomEvent('reference-style',{detail:profile}));$('ref-style-status').textContent='参考节奏已发送到创意剪辑；不会自动抓取账号内容，来源身份未核验。'}catch(e){$('ref-style-status').textContent=e.message}};

export async function localReferenceTask(run){
 if(scanning||!reference||!samples.length||!shots.length)throw Error('请先加载参考视频并完成拉片，或等待当前抽帧结束');scanning=true;const states=new Map([...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]));states.forEach((_,e)=>e.disabled=true);
 try{const frames=Array.from({length:Math.min(12,samples.length)},(_,i)=>samples[Math.round(i*(samples.length-1)/Math.max(1,Math.min(12,samples.length)-1))]).map(({time,image})=>({time,image}));say('本地视觉模型正在分析参考帧与文案；稀疏抽帧不能确定全部效果。');const result=await run({reference,frames,shots:shots.map(({start,end,note,copy,effect})=>({start,end,note,copy,effect})),transcript:$('ref-transcript').value});lastReport=localReport()+'\n\n## 本地视觉模型补充（推断，需核对）\n'+(result.skill?'参考 Skill：'+result.skill.name+'\n来源：'+result.skill.url+'\n版本：'+result.skill.commit+'\n方式：'+result.skill.method+'\n\n':'')+result.analysis;$('ref-output').textContent=lastReport;say('本地视觉分析已加入报告，不能视为原工程还原。');return result;
 }finally{scanning=false;states.forEach((disabled,e)=>e.disabled=disabled)}
}
